	dlasq1.ndarray(); // $ExpectError
	dlasq1.ndarray( 3 ); // $ExpectError
	dlasq1.ndarray( 3, D ); // $ExpectError
	dlasq1.ndarray( 3, D, 1 ); // $ExpectError
	dlasq1.ndarray( 3, D, 1, 0 ); // $ExpectError
	dlasq1.ndarray( 3, D, 1, 0, E ); // $ExpectError
